import Foundation
import TerminalDeckNativeCore

/// Exact source catalogue metadata; handlers are supplied by the factories below.
public enum BackendDeckToolsAppMetadata {
 public struct Entry: Sendable {
  public let module: String, title: String, index: String
  public let audience: String?
  public let aliases: [String]
  public let spec: BackendMCPTool
 }
 public static func entries() throws -> [Entry] {
  var entries: [Entry] = []
  entries.append(Entry(module: "app-tools", title: "About this app", index: "This app’s version, update channel, and where it keeps its files.", audience: nil, aliases: [], spec: try BackendMCPTool(id: "app.about", wireName: "app_about", description: "This app’s name, version, the Electron/Chromium/Node versions it runs on, its licence and repository, whether it can update itself, and every place it keeps its files (settings, state, accounts, logs) with whether each exists yet. The place keys here are what app.reveal takes.", inputSchema: try NativeRPCValue.parseJSON(Data(#"{"type":"object","properties":{},"additionalProperties":false}"#.utf8)), tier: .read)))
  entries.append(Entry(module: "app-tools", title: "Show one of the app’s folders in Finder", index: "Open one of the app’s folders (or its logs) in Finder.", audience: nil, aliases: [], spec: try BackendMCPTool(id: "app.reveal", wireName: "app_reveal", description: "Open one of the places this app keeps its files in Finder on this Mac, for the person to look at: a key from app.about’s places, or \"logs\" for the log folder. A file is revealed, not opened.", inputSchema: try NativeRPCValue.parseJSON(Data(#"{"type":"object","properties":{"place":{"type":"string","description":"A key from app.about, or \"logs\"."}},"required":["place"],"additionalProperties":false}"#.utf8)), tier: .act)))
  entries.append(Entry(module: "app-tools", title: "Collect diagnostics", index: "Collect the redacted support bundle: versions, agent CLIs, environment, log tail.", audience: nil, aliases: [], spec: try BackendMCPTool(id: "app.diagnostics", wireName: "app_diagnostics", description: "The support bundle the Debug panel builds: app and system versions, which agent CLIs were found and their versions, which parts of the app wired themselves up, the PATH and shell, and the end of the log — with secrets already redacted. text gives the same as one pasteable report. Probing the CLIs takes a couple of seconds; includeClis false skips it.", inputSchema: try NativeRPCValue.parseJSON(Data(#"{"type":"object","properties":{"text":{"type":"boolean","description":"One pasteable report instead of structured data."},"includeClis":{"type":"boolean","description":"Probe the agent CLIs. Default true."},"logLines":{"type":"number","description":"Lines of log to include. Default 200."}},"additionalProperties":false}"#.utf8)), tier: .read)))
  entries.append(Entry(module: "app-tools", title: "Read the app’s log", index: "Read the newest lines of the app’s log, or its recent internal calls.", audience: nil, aliases: [], spec: try BackendMCPTool(id: "app.log", wireName: "app_log", description: "The newest lines of the app’s own log (source \"app\"), redacted, or the record of recent calls between its window and its main process (source \"calls\": which channel, how long, whether it failed — never what was sent). Use when something in the app is not working and you need to see why.", inputSchema: try NativeRPCValue.parseJSON(Data(#"{"type":"object","properties":{"source":{"type":"string","enum":["app","calls"],"description":"Default app."},"lines":{"type":"number","description":"How many, newest last. Default 200, max 2000."}},"additionalProperties":false}"#.utf8)), tier: .read)))
  entries.append(Entry(module: "app-tools", title: "Clear the app’s log", index: "Empty the app’s log or its internal call record.", audience: nil, aliases: [], spec: try BackendMCPTool(id: "app.clear_log", wireName: "app_clear_log", description: "Empty the app’s log (source \"app\") or its record of recent internal calls (source \"calls\"). What is cleared cannot be read back.", inputSchema: try NativeRPCValue.parseJSON(Data(#"{"type":"object","properties":{"source":{"type":"string","enum":["app","calls"]}},"required":["source"],"additionalProperties":false}"#.utf8)), tier: .alter)))
  entries.append(Entry(module: "app-tools", title: "Reset settings to defaults", index: "Reset the app’s settings to defaults (protected ones are kept).", audience: nil, aliases: [], spec: try BackendMCPTool(id: "settings.reset", wireName: "settings_reset", description: "Put every app setting back to its default, as Settings → Reset does — except the protected ones (anything under `remote.`, `hoot.`, `copilot.`, `security.` or `confine.`, plus browser.persistSession and advanced.debugMode), which are never changed through these tools and are left exactly as they are. A copy of the current settings is saved first; the result names it and the keys that were kept. Preferences (theme, default agent) are not touched — use settings.write for those.", inputSchema: try NativeRPCValue.parseJSON(Data(#"{"type":"object","properties":{},"additionalProperties":false}"#.utf8)), tier: .alter)))
  entries.append(Entry(module: "app-tools", title: "Clear the browser’s data", index: "Delete the built-in browser’s cookies, storage and cache.", audience: nil, aliases: [], spec: try BackendMCPTool(id: "settings.clear_browser_data", wireName: "settings_clear_browser_data", description: "Delete the cookies, site storage and cache of the app’s built-in browser tab, as Settings does. Every site it was signed in to is signed out. Cannot be undone.", inputSchema: try NativeRPCValue.parseJSON(Data(#"{"type":"object","properties":{},"additionalProperties":false}"#.utf8)), tier: .alter)))
  entries.append(Entry(module: "app-tools", title: "Check for an update", index: "Whether a newer version of this app is available; can ask the update server now.", audience: nil, aliases: [], spec: try BackendMCPTool(id: "updates.status", wireName: "updates_status", description: "Whether a newer version of this app is available, downloading, or downloaded and ready to install. With check true it asks the update server now rather than reporting the last answer. Nothing is downloaded or installed.", inputSchema: try NativeRPCValue.parseJSON(Data(#"{"type":"object","properties":{"check":{"type":"boolean","description":"Ask the update server now. Default false."}},"additionalProperties":false}"#.utf8)), tier: .read)))
  entries.append(Entry(module: "app-tools", title: "Download an update", index: "Download the available update without installing it.", audience: nil, aliases: [], spec: try BackendMCPTool(id: "updates.download", wireName: "updates_download", description: "Download the update updates.status found. It is staged and installs the next time the app quits, or now with updates.install. Nothing restarts.", inputSchema: try NativeRPCValue.parseJSON(Data(#"{"type":"object","properties":{},"additionalProperties":false}"#.utf8)), tier: .act)))
  entries.append(Entry(module: "app-tools", title: "Install an update and restart", index: "Install the downloaded update; the app restarts and this connection drops.", audience: nil, aliases: [], spec: try BackendMCPTool(id: "updates.install", wireName: "updates_install", description: "Install the downloaded update now. The app QUITS AND RESTARTS: every running session is stopped (the app reopens them if the person has that turned on), and this MCP connection drops and comes back once the new version is up — so expect this call to end without an answer. Do not retry it; reconnect and read updates.status or app.about to see the new version.", inputSchema: try NativeRPCValue.parseJSON(Data(#"{"type":"object","properties":{},"additionalProperties":false}"#.utf8)), tier: .alter)))
  entries.append(Entry(module: "hook-tools", title: "Read the agents’ hook status", index: "Read whether the agents’ hooks are installed and working.", audience: nil, aliases: [], spec: try BackendMCPTool(id: "hooks.status", wireName: "hooks_status", description: "For each coding agent: whether this app’s hooks are installed in its settings file, aimed at this copy (complete), aimed somewhere dead (stale), partly there, or absent — with which events, which hooks belong to other tools, and one sentence saying why. Also whether this app’s hook listener is running, and whether the first-run offer is still waiting for an answer. Without hooks a session cannot say it needs attention the moment it does.", inputSchema: try NativeRPCValue.parseJSON(Data(#"{"type":"object","properties":{},"additionalProperties":false}"#.utf8)), tier: .read)))
  entries.append(Entry(module: "hook-tools", title: "Install the agents’ hooks", index: "Install this app’s hooks into an agent’s settings, or into every agent.", audience: nil, aliases: [], spec: try BackendMCPTool(id: "hooks.install", wireName: "hooks_install", description: "Install this app’s hooks into one agent’s settings file, or with \"all\" into every installed agent that has none yet (the first-run offer’s yes). Other tools’ hooks in the same file are never touched, and the untouched original is backed up before the first write. Some agents then ask the person to trust the new hooks themselves; the result says so.", inputSchema: try NativeRPCValue.parseJSON(Data(#"{"type":"object","properties":{"agent":{"type":"string","enum":["claude","codex","gemini","all"],"description":"Which agent, or \"all\" for every installed agent that has none yet."}},"required":["agent"],"additionalProperties":false}"#.utf8)), tier: .alter)))
  entries.append(Entry(module: "hook-tools", title: "Remove the agents’ hooks", index: "Remove this app’s hooks from an agent’s settings.", audience: nil, aliases: [], spec: try BackendMCPTool(id: "hooks.remove", wireName: "hooks_remove", description: "Take this app’s hooks out of one agent’s settings file. Other tools’ hooks stay. Its sessions then stop reporting their state the moment it changes.", inputSchema: try NativeRPCValue.parseJSON(Data(#"{"type":"object","properties":{"agent":{"type":"string","enum":["claude","codex","gemini"],"description":"Which agent."}},"required":["agent"],"additionalProperties":false}"#.utf8)), tier: .alter)))
  entries.append(Entry(module: "hook-tools", title: "Repair the agents’ hooks", index: "Repair stale or partial hooks so they point at this app again.", audience: nil, aliases: [], spec: try BackendMCPTool(id: "hooks.sync", wireName: "hooks_sync", description: "Re-aim every installed hook that points somewhere dead (a stale copy, an old socket) at this copy of the app, and fill in any missing events. Agents with no hooks are left alone. Use it when hooks.status says stale or partial.", inputSchema: try NativeRPCValue.parseJSON(Data(#"{"type":"object","properties":{},"additionalProperties":false}"#.utf8)), tier: .alter)))
  entries.append(Entry(module: "hook-tools", title: "Decline the hooks offer", index: "Say no to the first-run hooks question so it is not asked again.", audience: nil, aliases: [], spec: try BackendMCPTool(id: "hooks.decline_offer", wireName: "hooks_decline_offer", description: "Answer the first-run question \"install hooks?\" with no, so it stops being asked. Installs nothing and removes nothing; hooks.install still works afterwards.", inputSchema: try NativeRPCValue.parseJSON(Data(#"{"type":"object","properties":{},"additionalProperties":false}"#.utf8)), tier: .act)))
  entries.append(Entry(module: "memory-tools", title: "Search your memory", index: "Search the memory notes your agent keeps for this project (or, for Hoot, a project it names).", audience: "copilot", aliases: [], spec: try BackendMCPTool(id: "memory.search", wireName: "memory_search", description: "Search the memory notes you keep — the ones your agent reads at the start of a conversation — by words. A session searches its own memory for the folder it runs in; Hoot searches its own, and may add `project` to read one open project’s memory and knowledge for planning. Answers each note’s place, title and the line that matched; memory.read opens one. What comes back goes to you as tool output.", inputSchema: try NativeRPCValue.parseJSON(Data(#"{"type":"object","properties":{"query":{"type":"string","description":"Words to look for."},"project":{"type":"string","description":"Hoot only: an open project folder whose memory to read too."},"limit":{"type":"number","description":"Most results, 1–40. Default 10."}},"required":["query"],"additionalProperties":false}"#.utf8)), tier: .read)))
  entries.append(Entry(module: "memory-tools", title: "Read your memory", index: "Read one of your memory notes, with what it links to and what links to it — or list them all.", audience: "copilot", aliases: [], spec: try BackendMCPTool(id: "memory.read", wireName: "memory_read", description: "Read one memory note by its `path` (as memory.search or a listing gives it): its text, the notes it links to, the links that reach nothing, and the notes that link to it. Without `path`, lists the notes in your memory. Same scope as memory.search: your own memory, and for Hoot a named `project`’s, read-only. Pass `space` when more than one memory is in scope. What comes back goes to you as tool output.", inputSchema: try NativeRPCValue.parseJSON(Data(#"{"type":"object","properties":{"path":{"type":"string","description":"The note, relative to its memory folder. Omit to list."},"space":{"type":"string","description":"Which memory, when more than one is in scope."},"project":{"type":"string","description":"Hoot only: an open project folder whose memory to read."}},"additionalProperties":false}"#.utf8)), tier: .read)))
  entries.append(Entry(module: "routine-tools", title: "List routines", index: "List the routines (saved prompts that run on a trigger) and how each is doing.", audience: nil, aliases: [], spec: try BackendMCPTool(id: "routines.list", wireName: "routines_list", description: "Every routine on this computer: what triggers it, the folder it runs in, whether it is armed, paused or broken and why, when it last ran and how that went, when it is next due, and any calls its runs were not allowed to make. A routine is a saved prompt Hoot runs on a trigger — a schedule, a session finishing, an alert, a file change — with nobody watching.", inputSchema: try NativeRPCValue.parseJSON(Data(#"{"type":"object","properties":{},"additionalProperties":false}"#.utf8)), tier: .read)))
  entries.append(Entry(module: "routine-tools", title: "Read a routine", index: "Read one routine in full, including its file text.", audience: nil, aliases: [], spec: try BackendMCPTool(id: "routines.get", wireName: "routines_get", description: "One routine in full: its state and history, and the text of its file exactly as written (a short header of when:/in: lines, then the prompt). Read this before changing one with routines.save.", inputSchema: try NativeRPCValue.parseJSON(Data(#"{"type":"object","properties":{"routineId":{"type":"string","description":"The routine id from routines.list, like nightly-sweep."}},"required":["routineId"],"additionalProperties":false}"#.utf8)), tier: .read)))
  entries.append(Entry(module: "routine-tools", title: "Create or change a routine", index: "Create a routine, or change one (fields left out stay as they are).", audience: nil, aliases: [], spec: try BackendMCPTool(id: "routines.save", wireName: "routines_save", description: "Create a routine, or change one by naming its routineId. A new one needs name, when, folder and prompt. When changing, fields you leave out keep their current values. The routine is checked by the same parser its file goes through, and every problem is named. The person confirms it. A routine runs with nobody at the machine, so anything it would need confirmed is refused at the time and reported.", inputSchema: try NativeRPCValue.parseJSON(Data(#"{"type":"object","properties":{"routineId":{"type":"string","description":"To change one. For a new one, optional: lowercase-with-hyphens."},"name":{"type":"string","description":"What it is called."},"when":{"type":"array","items":{"type":"string"},"description":"One or more triggers: \"schedule 02:30\", \"schedule weekdays 09:00\", \"schedule every 30m\", \"session-finished\", \"session-failed\", \"session-idle 15m\", \"alert\", \"alert critical\", \"git-change\", \"file-change src/**\", \"manual\"."},"folder":{"type":"string","description":"The open folder it runs in and watches. See projects.list."},"prompt":{"type":"string","description":"What Hoot is told to do each time it runs."},"enabled":{"type":"boolean"},"overlap":{"type":"string","enum":["queue","skip","cancel"],"description":"If it fires while still running."},"maxRunsPerHour":{"type":"number"},"maxRunsPerDay":{"type":"number"},"quietFor":{"type":"string","description":"Wait for things to settle first, like 30s."},"expectEvery":{"type":"string","description":"Warn if it has not run in this long, like 1d."}},"additionalProperties":false}"#.utf8)), tier: .alter)))
  entries.append(Entry(module: "routine-tools", title: "Delete a routine", index: "Delete a routine.", audience: nil, aliases: [], spec: try BackendMCPTool(id: "routines.delete", wireName: "routines_delete", description: "Delete a routine’s file. It stops running at once. A run already in progress finishes.", inputSchema: try NativeRPCValue.parseJSON(Data(#"{"type":"object","properties":{"routineId":{"type":"string","description":"The routine id from routines.list, like nightly-sweep."}},"required":["routineId"],"additionalProperties":false}"#.utf8)), tier: .alter)))
  entries.append(Entry(module: "routine-tools", title: "Run a routine now", index: "Run a routine now.", audience: nil, aliases: [], spec: try BackendMCPTool(id: "routines.run", wireName: "routines_run", description: "Run a routine now, whatever its triggers say, within its own limits on runs per hour and per day. Returns at once with the run id; routines.get shows how it went.", inputSchema: try NativeRPCValue.parseJSON(Data(#"{"type":"object","properties":{"routineId":{"type":"string","description":"The routine id from routines.list, like nightly-sweep."}},"required":["routineId"],"additionalProperties":false}"#.utf8)), tier: .act)))
  entries.append(Entry(module: "routine-tools", title: "Pause a routine", index: "Pause a routine without editing it.", audience: nil, aliases: [], spec: try BackendMCPTool(id: "routines.pause", wireName: "routines_pause", description: "Stop a routine from firing without touching its file, with a reason the person will see. routines.resume arms it again.", inputSchema: try NativeRPCValue.parseJSON(Data(#"{"type":"object","properties":{"routineId":{"type":"string","description":"The routine id from routines.list, like nightly-sweep."},"reason":{"type":"string","description":"One sentence, shown to the person."}},"required":["routineId"],"additionalProperties":false}"#.utf8)), tier: .act)))
  entries.append(Entry(module: "routine-tools", title: "Resume a routine", index: "Resume a paused routine.", audience: nil, aliases: [], spec: try BackendMCPTool(id: "routines.resume", wireName: "routines_resume", description: "Arm a paused routine again.", inputSchema: try NativeRPCValue.parseJSON(Data(#"{"type":"object","properties":{"routineId":{"type":"string","description":"The routine id from routines.list, like nightly-sweep."}},"required":["routineId"],"additionalProperties":false}"#.utf8)), tier: .act)))
  entries.append(Entry(module: "copilot-admin-tools", title: "Hoot’s state", index: "Whether Hoot is running, signed in, which folder and account it uses, and its files.", audience: nil, aliases: ["copilot.state","copilot_state"], spec: try BackendMCPTool(id: "hoot.state", wireName: "hoot_state", description: "Hoot, the assistant built into this app (pinned at the top of the sidebar): whether it is running and its session id, whether it is signed in and as which account and plan, the folder it works in (and why, if a chosen folder could not be used), its startup files and whether its instructions are the default.", inputSchema: try NativeRPCValue.parseJSON(Data(#"{"type":"object","properties":{},"additionalProperties":false}"#.utf8)), tier: .read)))
  entries.append(Entry(module: "copilot-admin-tools", title: "Start, stop or set up Hoot", index: "Start or stop Hoot, create its folder and starter files, or open one of its places in Finder.", audience: nil, aliases: ["copilot.run","copilot_run"], spec: try BackendMCPTool(id: "hoot.run", wireName: "hoot_run", description: "\"start\" starts Hoot if it is not running (it spends money like any agent session). \"stop\" ends its session — confirmed, and if you ARE Hoot it ends you. \"scaffold\" writes its folder and starter files without starting it, so they can be read first. \"reveal\" opens one of its places in Finder on this Mac: root, instructions, memory, log, routines, layer, contract, composed. A changed instruction file takes effect at the next start.", inputSchema: try NativeRPCValue.parseJSON(Data(#"{"type":"object","properties":{"action":{"type":"string","enum":["start","stop","scaffold","reveal"]},"place":{"type":"string","enum":["root","instructions","memory","log","routines","layer","contract","composed"],"description":"For \"reveal\"."}},"required":["action"],"additionalProperties":false}"#.utf8)), tier: .act)))
  entries.append(Entry(module: "copilot-admin-tools", title: "What Hoot is told", index: "Read or change Hoot’s instructions — yours, its folder’s, the generated part, or all composed.", audience: nil, aliases: ["copilot.instructions","copilot_instructions"], spec: try BackendMCPTool(id: "hoot.instructions", wireName: "hoot_instructions", description: "Hoot’s instructions, the same four the Settings pane shows. \"read\" with `which`: \"yours\" (the part the person edits), \"folder\" (the working folder’s own instructions file), \"contract\" (generated from what is wired — read only), \"composed\" (everything it was handed at its last start). \"write\" replaces \"yours\" or \"folder\" with `text`; the previous file is kept beside it. \"reset\" puts this build’s default wording back. Writes are confirmed, and reach Hoot only at its next start.", inputSchema: try NativeRPCValue.parseJSON(Data(#"{"type":"object","properties":{"action":{"type":"string","enum":["read","write","reset"]},"which":{"type":"string","enum":["yours","folder","contract","composed"]},"text":{"type":"string","description":"For \"write\": the whole new file."}},"required":["action"],"additionalProperties":false}"#.utf8)), tier: .read)))
  entries.append(Entry(module: "copilot-admin-tools", title: "What Hoot remembers", index: "List, read, write or delete Hoot’s remembered facts.", audience: nil, aliases: ["copilot.memory","copilot_memory"], spec: try BackendMCPTool(id: "hoot.memory", wireName: "hoot_memory", description: "Hoot’s memory: one small file per remembered fact, in its memory folder. \"list\" names them, \"read\" returns one, \"write\" saves one (a new name creates it), \"delete\" removes one — confirmed. A name is a plain file name with no folders in it.", inputSchema: try NativeRPCValue.parseJSON(Data(#"{"type":"object","properties":{"action":{"type":"string","enum":["list","read","write","delete"]},"name":{"type":"string"},"text":{"type":"string","description":"For \"write\"."}},"required":["action"],"additionalProperties":false}"#.utf8)), tier: .read)))
  entries.append(Entry(module: "copilot-admin-tools", title: "This tool server’s status", index: "This tool server: its tools and tiers, how many confirmations are waiting, whether the log is written.", audience: nil, aliases: [], spec: try BackendMCPTool(id: "tools.status", wireName: "tools_status", description: "The state of this tool server: every tool and its tier, what the listing costs in tokens, how many confirmations are waiting for a person right now, which sessions Hoot started, and whether the action log is actually being written. Never a token or a key.", inputSchema: try NativeRPCValue.parseJSON(Data(#"{"type":"object","properties":{},"additionalProperties":false}"#.utf8)), tier: .read)))
  entries.append(Entry(module: "copilot-admin-tools", title: "Do notifications reach the person", index: "Whether this app’s banners actually reach the person’s screen; can open the system notification settings.", audience: nil, aliases: [], spec: try BackendMCPTool(id: "notifications.status", wireName: "notifications_status", description: "Whether this app’s notification banners actually reached the screen recently (read from macOS’s own record where it can be), and whether the system pane for them exists here. Set `openSettings` to open that pane on this Mac — for the person to change, since nothing here changes system settings.", inputSchema: try NativeRPCValue.parseJSON(Data(#"{"type":"object","properties":{"sinceMinutes":{"type":"integer","description":"How far back to look. Default 60, max 10080."},"openSettings":{"type":"boolean"}},"additionalProperties":false}"#.utf8)), tier: .read)))
  entries.append(Entry(module: "copilot-admin-tools", title: "Open a link in the Mac’s browser", index: "Open a web link in this Mac’s own default browser (not the in-app one — use browser.open for that).", audience: nil, aliases: [], spec: try BackendMCPTool(id: "links.open", wireName: "links_open", description: "Open a web address in this Mac’s own default browser, the way \"Open in your browser\" does. Only http and https. For a page you want to read or drive, use browser.open, which opens it inside the app.", inputSchema: try NativeRPCValue.parseJSON(Data(#"{"type":"object","properties":{"url":{"type":"string"}},"required":["url"],"additionalProperties":false}"#.utf8)), tier: .act)))
  entries.append(Entry(module: "usage-tools", title: "Read plan limits and context use", index: "Read plan-limit use and context-window fullness for a session or every login.", audience: nil, aliases: [], spec: try BackendMCPTool(id: "usage.read", wireName: "usage_read", description: "For a session: how much of its account’s plan limits are used and when they reset (as far as the agent has reported them), and how full its context window is. With no sessionId: the limits of every login on this computer. A figure the agent has not reported is said to be missing, never guessed. usage.refresh fetches fresh plan figures.", inputSchema: try NativeRPCValue.parseJSON(Data(#"{"type":"object","properties":{"sessionId":{"type":"string","description":"A session from sessions.list. Omit for every login."}},"additionalProperties":false}"#.utf8)), tier: .read)))
  entries.append(Entry(module: "usage-tools", title: "Refresh plan limits", index: "Fetch fresh plan-limit figures for a session’s account.", audience: nil, aliases: [], spec: try BackendMCPTool(id: "usage.refresh", wireName: "usage_refresh", description: "Bring a session’s account’s plan-limit figures up to date. Reads what is on disk first and, only if that is not enough, runs a short Claude Code of its own to ask — it never types into the session. Skips when the figures are fresh or the login has no plan limits, unless force is true.", inputSchema: try NativeRPCValue.parseJSON(Data(#"{"type":"object","properties":{"sessionId":{"type":"string"},"force":{"type":"boolean","description":"Ask even when the figures are recent. Default false."}},"required":["sessionId"],"additionalProperties":false}"#.utf8)), tier: .act)))
  entries.append(Entry(module: "usage-tools", title: "Read what a project has cost", index: "Read token use and cost for a folder, or for one session in it.", audience: nil, aliases: [], spec: try BackendMCPTool(id: "usage.cost", wireName: "usage_cost", description: "Token use and cost for an open folder: the totals across its recent sessions and the list of its session transcripts, newest first. Give transcriptPath (from that list) to get one session’s breakdown instead. Counted once per request even where a transcript repeats it, exactly as the app’s own cost tiles count.", inputSchema: try NativeRPCValue.parseJSON(Data(#"{"type":"object","properties":{"projectPath":{"type":"string","description":"An open folder. See projects.list."},"transcriptPath":{"type":"string","description":"One of that folder’s transcripts, for one session."},"limit":{"type":"number","description":"How many transcripts to list. Default 20, max 100."}},"required":["projectPath"],"additionalProperties":false}"#.utf8)), tier: .read)))
  entries.append(Entry(module: "voice-tools", title: "Read the dictation setup", index: "Whether dictation has a transcription key, and which providers are offered.", audience: nil, aliases: [], spec: try BackendMCPTool(id: "voice.status", wireName: "voice_status", description: "Whether dictation can transcribe on this computer: which providers are offered (with their model and where a key is issued), whether a key is stored and which provider it is for, and whether this computer can store one securely at all. The key itself is never returned.", inputSchema: try NativeRPCValue.parseJSON(Data(#"{"type":"object","properties":{},"additionalProperties":false}"#.utf8)), tier: .read)))
  entries.append(Entry(module: "voice-tools", title: "Save a transcription key", index: "Store a transcription API key for dictation (it is checked first, never shown back).", audience: nil, aliases: [], spec: try BackendMCPTool(id: "voice.save_key", wireName: "voice_save_key", description: "Store an API key for one dictation provider. The key is tried against the provider first and stored only if it works — the result says which. It replaces any key already stored, is kept in the operating system’s secure store, and is never shown back. The person confirms it.", inputSchema: try NativeRPCValue.parseJSON(Data(#"{"type":"object","properties":{"provider":{"type":"string","description":"A provider id from voice.status."},"key":{"type":"string","description":"The API key."}},"required":["provider","key"],"additionalProperties":false}"#.utf8)), tier: .alter)))
  entries.append(Entry(module: "voice-tools", title: "Forget the transcription key", index: "Delete the stored dictation key.", audience: nil, aliases: [], spec: try BackendMCPTool(id: "voice.forget_key", wireName: "voice_forget_key", description: "Delete the stored dictation key. The microphone button goes away until another key is saved.", inputSchema: try NativeRPCValue.parseJSON(Data(#"{"type":"object","properties":{},"additionalProperties":false}"#.utf8)), tier: .alter)))
  entries.append(Entry(module: "voice-tools", title: "Transcribe a recording", index: "Turn a recording (base64 audio) into text with the dictation key.", audience: nil, aliases: [], spec: try BackendMCPTool(id: "voice.transcribe", wireName: "voice_transcribe", description: "Turn a recording into text with the stored dictation key — the same request the microphone button makes. Send the audio as base64 (webm, wav, mp3, m4a or ogg), up to 20 MB. Uses the person’s API credit with that provider. Needs a key; voice.status says whether there is one.", inputSchema: try NativeRPCValue.parseJSON(Data(#"{"type":"object","properties":{"audio":{"type":"string","description":"The recording, base64-encoded."},"filename":{"type":"string","description":"Its name with the right extension, e.g. note.m4a. Default speech.webm."}},"required":["audio"],"additionalProperties":false}"#.utf8)), tier: .act)))
  entries.append(Entry(module: "setup-tools", title: "Check this computer’s setup", index: "Check which agent CLIs and tools are installed and signed in on this computer.", audience: nil, aliases: [], spec: try BackendMCPTool(id: "setup.status", wireName: "setup_status", description: "Whether this computer can run agent sessions: each agent CLI (installed, which version, signed in, out of date), the tools they need, and whether at least one agent is ready. When nothing works, this says what is missing and how to install it. Takes a few seconds — it runs each CLI.", inputSchema: try NativeRPCValue.parseJSON(Data(#"{"type":"object","properties":{},"additionalProperties":false}"#.utf8)), tier: .read)))
  entries.append(Entry(module: "setup-tools", title: "Score a folder’s readiness for agents", index: "Score how ready an open folder is for coding agents, with a fix for each gap.", audience: nil, aliases: [], spec: try BackendMCPTool(id: "readiness.scan", wireName: "readiness_scan", description: "Score an open folder 0–100 on how ready it is for a coding agent — an instructions file, a README, git, ignore rules, a test and typecheck script, a lockfile, secrets kept out of the repository — with what was found for each, and the fix on offer for each gap (what it does and which files it touches). Graded per agent too. Read-only.", inputSchema: try NativeRPCValue.parseJSON(Data(#"{"type":"object","properties":{"projectPath":{"type":"string","description":"An open folder. See projects.list."}},"required":["projectPath"],"additionalProperties":false}"#.utf8)), tier: .read)))
  entries.append(Entry(module: "setup-tools", title: "Apply a readiness fix", index: "Apply one of the fixes readiness.scan offers for a folder.", audience: nil, aliases: [], spec: try BackendMCPTool(id: "readiness.fix", wireName: "readiness_fix", description: "Apply one fix readiness.scan offers for an open folder — create an instructions file or a .gitignore, add a test script, stop tracking a committed secret, upgrade an agent CLI. Only a fix the folder’s scan is offering right now can be applied. It writes into the project, so the person confirms it; the result lists the files that changed.", inputSchema: try NativeRPCValue.parseJSON(Data(#"{"type":"object","properties":{"projectPath":{"type":"string"},"fixId":{"type":"string","description":"The fix id from readiness.scan."}},"required":["projectPath","fixId"],"additionalProperties":false}"#.utf8)), tier: .alter)))
  entries.append(Entry(module: "ui-tools", title: "What can be done in the window", index: "The app window’s commands, the sessions it can bring to the front, and its Settings sections — for ui.do.", audience: nil, aliases: [], spec: try BackendMCPTool(id: "ui.list", wireName: "ui_list", description: "What the app window can be told to do with ui.do right now: every command in its palette (views like Files, Source control, Overview; split or swarm the window; show or hide the sidebar; open Settings, Help, the session inspector), the sessions it can bring to the front, and the Settings sections it can open. `refused` lists the commands ui.do will not run because they wait for typing, and the tool to use for each. Use app.where to see what is on screen now.", inputSchema: try NativeRPCValue.parseJSON(Data(#"{"type":"object","properties":{},"additionalProperties":false}"#.utf8)), tier: .read)))
  entries.append(Entry(module: "ui-tools", title: "Do something in the window", index: "Do what a click does in the app window: open a view, bring a session to the front, open Settings.", audience: nil, aliases: [], spec: try BackendMCPTool(id: "ui.do", wireName: "ui_do", description: "Do in the app window what a person does by clicking: `action: \"run\"` runs a palette command by id (ui.list has them — e.g. \"view.files\", \"pane.split\", \"view.sidebar\"); \"focus\" brings a session to the front, by id; \"settings\" opens Settings at a section (\"general\", \"agents\", \"hoot\", …). Installing a feature (\"features.install.<id>\") is confirmed. Commands that open a dialog waiting for typing are refused with the tool that does the job. Not while a tour is playing.", inputSchema: try NativeRPCValue.parseJSON(Data(#"{"type":"object","properties":{"action":{"type":"string","enum":["run","focus","settings"]},"target":{"type":"string","description":"A command id, a session id, or a Settings section."}},"required":["action","target"],"additionalProperties":false}"#.utf8)), tier: .act)))
  entries.append(Entry(module: "github-tools", title: "Read GitHub for a project", index: "The GitHub repository, pull requests, checks and sign-in for one of this app’s project folders.", audience: nil, aliases: [], spec: try BackendMCPTool(id: "github.look", wireName: "github_look", description: "What GitHub says about the repository behind one of this app’s project folders: the repository, open pull requests and their checks, and whether this app is signed in to GitHub and as whom. Answers from a short cache; set refresh true to ask GitHub again. Use projects.list for the folders.", inputSchema: try NativeRPCValue.parseJSON(Data(#"{"type":"object","properties":{"folder":{"type":"string","description":"A project folder, from projects.list."},"refresh":{"type":"boolean","description":"Ask GitHub again rather than answering from the cache. Default false."}},"required":["folder"],"additionalProperties":false}"#.utf8)), tier: .read)))
  entries.append(Entry(module: "github-tools", title: "Sign this app in to GitHub, or out", index: "Sign this app in to or out of GitHub; returns the code to type at github.com.", audience: nil, aliases: [], spec: try BackendMCPTool(id: "github.connect", wireName: "github_connect", description: "This app’s own GitHub sign-in. Every call asks the person first. do: \"connect\" starts a sign-in and returns a short code and the github.com address where the person types it; \"wait\" then waits (up to two minutes per call) for them to finish and returns the new state; \"cancel\" abandons a sign-in that is waiting; \"disconnect\" signs this app out of GitHub. folder is optional and only decides which repository the answer describes.", inputSchema: try NativeRPCValue.parseJSON(Data(#"{"type":"object","properties":{"do":{"type":"string","enum":["connect","wait","cancel","disconnect"]},"folder":{"type":"string","description":"A project folder, for which repository the answer describes."}},"required":["do"],"additionalProperties":false}"#.utf8)), tier: .alter)))
  entries.append(Entry(module: "store-tools", title: "Read a page with an installed tool", index: "Read an attached page with a tool installed from the browser tools store. Call it naming no tool to list what is installed.", audience: nil, aliases: [], spec: try BackendMCPTool(id: "browser.extract", wireName: "browser_extract", description: "Run one of the tools installed from the browser tools store against an attached page and return what it collects. Call with no tool to list what is installed. Every answer says how many the page has and how many came back, so a partial read is never mistaken for a complete one.", inputSchema: try NativeRPCValue.parseJSON(Data(#"{"type":"object","properties":{"tool":{"type":"string","description":"Which installed tool to run. Omit to list the tools that are installed."},"sessionId":{"type":"string","description":"Whose window. Omit for your own."},"window":{"type":"string","description":"Window name, like B1. Omit for the first one."},"limit":{"type":"number","description":"Most rows to bring back, up to 2000."}},"additionalProperties":false}"#.utf8)), tier: .read)))
  entries.append(Entry(module: "tools-store-tools", title: "The browser’s Tools store", index: "Tools store of page readers for browser.extract: list, install, remove.", audience: nil, aliases: [], spec: try BackendMCPTool(id: "browser.store", wireName: "browser_store", description: "The browser’s Tools store: ready-made page readers that browser.extract then runs on a page. \"list\" (the default) gives every tool in the store — what it reads, which sites it runs on, whether it is installed, and the digest it is pinned to. \"install\" downloads, verifies and installs one (tool); \"remove\" takes one away. A store tool is a set of selectors, not a program, and can never read more than browser.read would. Install and remove ask the person first.", inputSchema: try NativeRPCValue.parseJSON(Data(#"{"type":"object","properties":{"action":{"type":"string","enum":["list","install","remove"],"description":"Default list."},"tool":{"type":"string","description":"For install and remove: the tool id from the list."}},"additionalProperties":false}"#.utf8)), tier: .read)))
  entries.append(Entry(module: "community-tools", title: "The Store’s Community shelf", index: "Store’s Community shelf of other people’s skills, MCP servers, hooks: list, install (runs their code; asks), remove.", audience: nil, aliases: [], spec: try BackendMCPTool(id: "store.community", wireName: "store_community", description: "The Store’s Community department: skills, instructions, MCP servers, hooks and routines other people published. \"list\" (the default) gives each item — what it is, who published it, what it needs, which sites it reaches, where it writes, whether it is installed, and in plain words what it runs on this Mac (kind and query narrow it). \"install\" installs one into this Mac’s agents (item; agents, values for an MCP server’s inputs, folder for a routine). Installing runs someone else’s work on this Mac — their instructions or their program — so the person is asked first and shown what it runs. \"remove\" takes an installed item away again, everything it wrote included.", inputSchema: try NativeRPCValue.parseJSON(Data(#"{"type":"object","properties":{"action":{"type":"string","enum":["list","install","remove"],"description":"Default list."},"item":{"type":"string","description":"For install and remove: the item id from the list."},"kind":{"type":"string","description":"For list: only one kind — skill, instructions, mcp, hooks, routine, extension, tool."},"query":{"type":"string","description":"For list: only items whose name, summary or tags contain this."},"agents":{"type":"array","items":{"type":"string"},"description":"For install: which agents to install it into (claude, codex, gemini). Omit for every one it supports."},"values":{"type":"object","description":"For install of an mcp item: its declared inputs by key, such as an API key. Never logged."},"folder":{"type":"string","description":"For install of a routine: the folder it runs in."}},"additionalProperties":false}"#.utf8)), tier: .read)))
  entries.append(Entry(module: "fixed-tools", title: "Stays Fixed: where a project stands", index: "Stays Fixed in one project: set up or not, its guards, the build marked good, the last check, and what this machine can check.", audience: nil, aliases: [], spec: try BackendMCPTool(id: "fixed.status", wireName: "fixed_status", description: "Stays Fixed is a regression safety net built into this app: it runs a project's product twice, compares it with the build last marked as good, and reports only differences nobody asked for. This answers where one project stands: whether it is set up (if not, fixed.setup), its guards (one plain-English rule per bug already fixed once), which build is marked as good, how the last check went and when, whether a check is running now, and whether agent sessions here get the Stays Fixed tools. Pass machine: true to also hear what this computer can and cannot check here and the exact fix for each gap — that part takes up to half a minute.", inputSchema: try NativeRPCValue.parseJSON(Data(#"{"type":"object","properties":{"project":{"type":"string","description":"The project folder, absolute, as projects.list names it."},"machine":{"type":"boolean","description":"Also say what this machine can check here. Slower."}},"required":["project"],"additionalProperties":false}"#.utf8)), tier: .read)))
  entries.append(Entry(module: "fixed-tools", title: "Set up Stays Fixed in a project", index: "Set Stays Fixed up in a project: it reads the repository and writes a settings file. Needs a git repository.", audience: nil, aliases: [], spec: try BackendMCPTool(id: "fixed.setup", wireName: "fixed_setup", description: "Set Stays Fixed up in a project — the page's Set up button. It reads the repository (package.json, the framework, routes, commands, built apps) and writes `staysfixed.config.js` with an explanation beside every option, plus three lines in .gitignore. It never overwrites a settings file that is already there. The project must be a git repository. Answers with what it wrote and anything only a person can do (a licence, a device, a password), each with its fix.", inputSchema: try NativeRPCValue.parseJSON(Data(#"{"type":"object","properties":{"project":{"type":"string","description":"The project folder, absolute, as projects.list names it."}},"required":["project"],"additionalProperties":false}"#.utf8)), tier: .alter)))
  entries.append(Entry(module: "fixed-tools", title: "Run a Stays Fixed check", index: "Check that nothing that already worked in a project has changed; answers with only the differences nobody asked for.", audience: nil, aliases: [], spec: try BackendMCPTool(id: "fixed.check", wireName: "fixed_check", description: "Run Stays Fixed on a project: it runs the product the way the settings say, compares it with the build marked as good, subtracts what the product disagrees with itself about, and answers with ONLY the differences nobody asked for — each with a plain title, the before and after values, and needsPerson when it touches money, signing in, lost data, a crash or a bug already fixed once (a person must look at those). Everything unchanged is one line with a count. If a check is already running here this joins it. Waits up to `wait` seconds (default 45, max 120); if it is still running then, it says what it is doing and you call fixed.results with a wait to collect the answer. verdict not-compared means nothing is marked as good yet — that is not a pass.", inputSchema: try NativeRPCValue.parseJSON(Data(#"{"type":"object","properties":{"project":{"type":"string","description":"The project folder, absolute, as projects.list names it."},"wait":{"type":"integer","description":"Seconds to wait for the answer, 0–120. Default 45."}},"required":["project"],"additionalProperties":false}"#.utf8)), tier: .act)))
  entries.append(Entry(module: "fixed-tools", title: "The last Stays Fixed check", index: "The last Stays Fixed check in a project — anybody's — with only its unintended differences; can wait for a running one.", audience: nil, aliases: [], spec: try BackendMCPTool(id: "fixed.results", wireName: "fixed_results", description: "The last Stays Fixed check in a project, whoever ran it — the page, an agent through Stays Fixed's own tools, a terminal — as only the differences nobody asked for, each with before and after, plus one line for everything unchanged and one for what was not looked at. Pass wait (seconds, max 120) to wait for a check that is running. Pass full: true for the full report: every change of every difference, the engine's own summary and every thing it did not look at with why.", inputSchema: try NativeRPCValue.parseJSON(Data(#"{"type":"object","properties":{"project":{"type":"string","description":"The project folder, absolute, as projects.list names it."},"wait":{"type":"integer","description":"Seconds to wait for a running check, 0–120. Default 0."},"full":{"type":"boolean","description":"The full report rather than the summary."}},"required":["project"],"additionalProperties":false}"#.utf8)), tier: .read)))
  entries.append(Entry(module: "fixed-tools", title: "Stop a Stays Fixed check", index: "Stop the Stays Fixed check running in a project.", audience: nil, aliases: [], spec: try BackendMCPTool(id: "fixed.stop", wireName: "fixed_stop", description: "Stop the Stays Fixed check running in a project. Stays Fixed puts away what it started first. Answers whether one was running.", inputSchema: try NativeRPCValue.parseJSON(Data(#"{"type":"object","properties":{"project":{"type":"string","description":"The project folder, absolute, as projects.list names it."}},"required":["project"],"additionalProperties":false}"#.utf8)), tier: .act)))
  entries.append(Entry(module: "fixed-tools", title: "Mark this build as good", index: "Ask the owner to mark the last-checked build as good, so every later Stays Fixed check compares against it.", audience: nil, aliases: [], spec: try BackendMCPTool(id: "fixed.mark_good", wireName: "fixed_mark_good", description: "Ask the owner to mark the build that was last checked as good — what every later check compares against. The owner is always asked, whatever this app's settings say about asking: deciding what \"working\" means is a person's call. It is refused for a build that was never checked, or whose check could not run — call fixed.check first. When the last check found differences it is refused too, unless anyway: true, which asks the owner to accept those differences as the new normal; say which differences in your message to them.", inputSchema: try NativeRPCValue.parseJSON(Data(#"{"type":"object","properties":{"project":{"type":"string","description":"The project folder, absolute, as projects.list names it."},"anyway":{"type":"boolean","description":"Accept the differences the last check found as the new normal."}},"required":["project"],"additionalProperties":false}"#.utf8)), tier: .alter)))
  entries.append(Entry(module: "fixed-tools", title: "Give agents Stays Fixed", index: "Turn on or off whether agent sessions started in a project get the Stays Fixed tools.", audience: nil, aliases: [], spec: try BackendMCPTool(id: "fixed.agents", wireName: "fixed_agents", description: "Whether every agent session started in a project from now on — Claude Code, Codex and Gemini — gets Stays Fixed's own tools (check its own work, explain a finding, prove a cause). On by default once a project is set up. Sessions already running keep what they started with. Nothing in the agents' own settings files is changed.", inputSchema: try NativeRPCValue.parseJSON(Data(#"{"type":"object","properties":{"project":{"type":"string","description":"The project folder, absolute, as projects.list names it."},"on":{"type":"boolean","description":"true to give it, false to stop giving it."}},"required":["project","on"],"additionalProperties":false}"#.utf8)), tier: .alter)))
  return entries
 }
